css:
:root {
  --bg-base: #0a0a0a;
  --bg-surface: #111111;
  --bg-card: #1f1f1f;
  --border: #2a2a2a;
  --text: #fafafa;
  --text-muted: #a1a1aa;
  --accent: #0ea5e9;
  --success: #22c55e;
  --danger: #ef4444;
  --warning: #f59e0b;

  /* Uma cor por fonte de receita — a mesma em pílula, gráfico e avatar. */
  --src-empresa: #0ea5e9;
  --src-impressionart: #8b5cf6;
  --src-moto: #f59e0b;
  --src-mos: #22c55e;
  --src-nata: #ec4899;

  --fonte: 'Manrope', sans-serif;
  --fonte-titulo: 'Sora', sans-serif;
  --fonte-mono: 'JetBrains Mono', monospace;
}

body { background: var(--bg-base); color: var(--text); font-family: var(--fonte); }

/* Número em tabela, card ou badge nunca "dança" ao atualizar. */
.bs-num { font-variant-numeric: tabular-nums; }

.bs-rows { width: min(560px, 100%); display: flex; flex-direction: column; gap: 8px; }

.bs-row {
  display: flex; align-items: center; gap: 12px;
  padding: 12px; border: 1px solid var(--border); border-radius: 12px; background: var(--bg-surface);
}

.bs-row-av {
  display: grid; place-items: center; flex-shrink: 0;
  width: 36px; height: 36px; border-radius: 10px;
  background: color-mix(in srgb, var(--cor) 15%, transparent);
}
.bs-row-av span { width: 10px; height: 10px; border-radius: 999px; background: var(--cor); }

/* min-width: 0 é o que permite o truncamento: sem ele o flex item cresce
   até o texto caber e a linha estoura. */
.bs-row-txt { flex: 1; min-width: 0; }
.bs-row-desc {
  font-size: 13px; font-weight: 600; color: var(--text);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.bs-row-leg {
  margin-top: 2px; font-size: 11px; color: var(--text-muted);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}

.bs-row-val {
  flex-shrink: 0;
  font-family: var(--fonte-titulo); font-size: 14px; font-weight: 600;
}
.bs-pos { color: var(--success); }
.bs-neg { color: var(--danger); }
